    public interface MSP {

        /**
        An MSP v2 payload is up to 65535 bytes, so the caps are raised past AdHoc's 255-item default; a v1 payload
        stays within 255.
        */
        enum _DefaultMaxLengthOf {
            Arrays  = 65_535,
            Maps    = 65_535,
            Sets    = 65_535,
            Strings = 65_535,
        }

        // ═════════════════════════ constants ═════════════════════════

        /**
        Non-command #defines of the MSP headers: protocol/API version, identifier lengths, capability bits,
        MSP2_GET_TEXT variable ids.
        */
        public struct Constants {
            /**
            Protocol numbers used both by the wire format, config system, and field setters.
            */
            public const long MSP_PROTOCOL_VERSION = 0;
            public const long API_VERSION_MAJOR = 1;
            public const long API_VERSION_MINOR = 49;
            public const long API_VERSION_LENGTH = 2;
            public const string MULTIWII_IDENTIFIER = "MWII";
            public const string BASEFLIGHT_IDENTIFIER = "BAFL";
            /**
            #define BETAFLIGHT_IDENTIFIER "BTFL" Actual value stored in FC_FIRMWARE_IDENTIFIER in build/version.h
            */
            public const string CLEANFLIGHT_IDENTIFIER = "CLFL";
            public const string INAV_IDENTIFIER = "INAV";
            public const string RACEFLIGHT_IDENTIFIER = "RCFL";
            public const long FLIGHT_CONTROLLER_IDENTIFIER_LENGTH = 4;
            public const long FLIGHT_CONTROLLER_VERSION_LENGTH = 3;
            public const long FLIGHT_CONTROLLER_VERSION_MASK = 0xFFF;
            /**
            4 UPPER CASE alpha numeric characters that identify the board being used.
            */
            public const long BOARD_IDENTIFIER_LENGTH = 4;
            public const long BOARD_HARDWARE_REVISION_LENGTH = 2;
            /**
            These are baseflight specific flags but they are useless now since MW 2.3 uses the upper 4 bits for the
            navigation version.
            */
            public const long CAP_PLATFORM_32BIT = 2147483648;
            public const long CAP_BASEFLIGHT_CONFIG = 1073741824;
            /**
            MW 2.3 stores NAVI_VERSION in the top 4 bits of the capability mask.
            */
            public const long CAP_NAVI_VERSION_BIT_4_MSB = 2147483648;
            public const long CAP_NAVI_VERSION_BIT_3 = 1073741824;
            public const long CAP_NAVI_VERSION_BIT_2 = 536870912;
            public const long CAP_NAVI_VERSION_BIT_1_LSB = 268435456;
            public const long CAP_DYNBALANCE = 4;
            public const long CAP_FLAPS = 8;
            public const long CAP_NAVCAP = 16;
            public const long CAP_EXTAUX = 32;
            /**
            MSPv2 payload indicator
            */
            public const long MSP_V2_FRAME = 255;
            /**
            MSP2_CLI_COMMAND response flags (byte following the u16 total-length header)
            output exceeded the pageable buffer
            */
            public const long MSP2_CLI_COMMAND_FLAG_TRUNCATED = 1;
            /**
            command refused or paging session mismatch
            */
            public const long MSP2_CLI_COMMAND_FLAG_REFUSED = 2;
            /**
            MSP2_SET_TEXT and MSP2_GET_TEXT variable types
            */
            public const long MSP2TEXT_PILOT_NAME = 1;
            public const long MSP2TEXT_CRAFT_NAME = 2;
            public const long MSP2TEXT_PID_PROFILE_NAME = 3;
            public const long MSP2TEXT_RATE_PROFILE_NAME = 4;
            public const long MSP2TEXT_BUILDKEY = 5;
            public const long MSP2TEXT_RELEASENAME = 6;
            /**
            CUSTOM_MSG_MAX_NUM  entries are allocated
            */
            public const long MSP2TEXT_CUSTOM_MSG_0 = 7;
            public const long CUSTOM_MSG_MAX_NUM = 4;
            public const long MSP2TEXT_BATTERY_PROFILE_NAME = 11;
        }

        /**
        Framing of an MSP frame on the serial link (msp_serial.c, iNav wiki MSP-V2):
        v1: '$' 'M' dir(&lt;|&gt;|!) size:u8 cmd:u8 payload crc8-xor;  v2: '$' 'X' dir flags:u8 function:u16 size:u16
        payload crc8-dvb-s2.
        A v2 frame may also ride inside a v1 frame with cmd = MSP_V2_FRAME (255).
        */
        public struct Framing {
            public const string V1_PREAMBLE = "$M";
            public const string V2_PREAMBLE = "$X";
            public const char DIRECTION_TO_FC = '<';
            public const char DIRECTION_FROM_FC = '>';
            public const char DIRECTION_ERROR = '!';
            public const long V1_MAX_PAYLOAD = 255;
            public const long V2_MAX_PAYLOAD = 65535;
        }

        // ═════════════════════════ command ids ═════════════════════════

