        // ═════════════════════════ topology ═════════════════════════

        // Betaflight Configurator, OSD, VTX or any MSP client
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Configurator : Host { }

        // Betaflight / iNav flight controller
        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct FlightController : Host { }

        interface MspLink : Connects<Configurator, FlightController> {
            // One RPC per MSP command: the configurator calls, the flight controller answers.
            /**
            out message: Get API version
            */
            (L____________, MSP_API_VERSION_Reply) MSP_API_VERSION(MSP_API_VERSION_Request req);
            /**
            out message: Get flight controller variant
            */
            (L____________, MSP_FC_VARIANT_Reply) MSP_FC_VARIANT(MSP_FC_VARIANT_Request req);
            /**
            out message: Get flight controller version
            */
            (L____________, MSP_FC_VERSION_Reply) MSP_FC_VERSION(MSP_FC_VERSION_Request req);
            /**
            out message: Get board information
            */
            (L____________, MSP_BOARD_INFO_Reply) MSP_BOARD_INFO(MSP_BOARD_INFO_Request req);
            /**
            out message: Get build information
            */
            (L____________, MSP_BUILD_INFO_Reply) MSP_BUILD_INFO(MSP_BUILD_INFO_Request req);
            /**
            out message: Returns user set board name - betaflight
            */
            (L____________, MSP_NAME_Reply) MSP_NAME(MSP_NAME_Request req);
            /**
            in message:  Sets board name - betaflight
            */
            (L____________, MSP_SET_NAME_Reply) MSP_SET_NAME(MSP_SET_NAME_Request req);
            /**
            Cleanflight original features (32-62)
            out message: Get battery configuration
            */
            (L____________, MSP_BATTERY_CONFIG_Reply) MSP_BATTERY_CONFIG(MSP_BATTERY_CONFIG_Request req);
            /**
            in message:  Set battery configuration
            */
            (L____________, MSP_SET_BATTERY_CONFIG_Reply) MSP_SET_BATTERY_CONFIG(MSP_SET_BATTERY_CONFIG_Request req);
            /**
            out message: Returns all mode ranges
            */
            (L____________, MSP_MODE_RANGES_Reply) MSP_MODE_RANGES(MSP_MODE_RANGES_Request req);
            /**
            in message:  Sets a single mode range
            */
            (L____________, MSP_SET_MODE_RANGE_Reply) MSP_SET_MODE_RANGE(MSP_SET_MODE_RANGE_Request req);
            /**
            out message: Get feature configuration
            */
            (L____________, MSP_FEATURE_CONFIG_Reply) MSP_FEATURE_CONFIG(MSP_FEATURE_CONFIG_Request req);
            /**
            in message:  Set feature configuration
            */
            (L____________, MSP_SET_FEATURE_CONFIG_Reply) MSP_SET_FEATURE_CONFIG(MSP_SET_FEATURE_CONFIG_Request req);
            /**
            out message: Get board alignment configuration
            */
            (L____________, MSP_BOARD_ALIGNMENT_CONFIG_Reply) MSP_BOARD_ALIGNMENT_CONFIG(MSP_BOARD_ALIGNMENT_CONFIG_Request req);
            /**
            in message:  Set board alignment configuration
            */
            (L____________, MSP_SET_BOARD_ALIGNMENT_CONFIG_Reply) MSP_SET_BOARD_ALIGNMENT_CONFIG(MSP_SET_BOARD_ALIGNMENT_CONFIG_Request req);
            /**
            out message: Get current meter configuration
            */
            (L____________, MSP_CURRENT_METER_CONFIG_Reply) MSP_CURRENT_METER_CONFIG(MSP_CURRENT_METER_CONFIG_Request req);
            /**
            in message:  Set current meter configuration
            */
            (L____________, MSP_SET_CURRENT_METER_CONFIG_Reply) MSP_SET_CURRENT_METER_CONFIG(MSP_SET_CURRENT_METER_CONFIG_Request req);
            /**
            out message: Get mixer configuration
            */
            (L____________, MSP_MIXER_CONFIG_Reply) MSP_MIXER_CONFIG(MSP_MIXER_CONFIG_Request req);
            /**
            in message:  Set mixer configuration
            */
            (L____________, MSP_SET_MIXER_CONFIG_Reply) MSP_SET_MIXER_CONFIG(MSP_SET_MIXER_CONFIG_Request req);
            /**
            out message: Get RX configuration
            */
            (L____________, MSP_RX_CONFIG_Reply) MSP_RX_CONFIG(MSP_RX_CONFIG_Request req);
            /**
            in message:  Set RX configuration
            */
            (L____________, MSP_SET_RX_CONFIG_Reply) MSP_SET_RX_CONFIG(MSP_SET_RX_CONFIG_Request req);
            /**
            out message: Get LED colors
            */
            (L____________, MSP_LED_COLORS_Reply) MSP_LED_COLORS(MSP_LED_COLORS_Request req);
            /**
            in message:  Set LED colors
            */
            (L____________, MSP_SET_LED_COLORS_Reply) MSP_SET_LED_COLORS(MSP_SET_LED_COLORS_Request req);
            /**
            out message: Get LED strip configuration
            */
            (L____________, MSP_LED_STRIP_CONFIG_Reply) MSP_LED_STRIP_CONFIG(MSP_LED_STRIP_CONFIG_Request req);
            /**
            in message:  Set LED strip configuration
            */
            (L____________, MSP_SET_LED_STRIP_CONFIG_Reply) MSP_SET_LED_STRIP_CONFIG(MSP_SET_LED_STRIP_CONFIG_Request req);
            /**
            out message: Get RSSI configuration
            */
            (L____________, MSP_RSSI_CONFIG_Reply) MSP_RSSI_CONFIG(MSP_RSSI_CONFIG_Request req);
            /**
            in message:  Set RSSI configuration
            */
            (L____________, MSP_SET_RSSI_CONFIG_Reply) MSP_SET_RSSI_CONFIG(MSP_SET_RSSI_CONFIG_Request req);
            /**
            out message: Get adjustment ranges
            */
            (L____________, MSP_ADJUSTMENT_RANGES_Reply) MSP_ADJUSTMENT_RANGES(MSP_ADJUSTMENT_RANGES_Request req);
            /**
            in message:  Set adjustment range
            */
            (L____________, MSP_SET_ADJUSTMENT_RANGE_Reply) MSP_SET_ADJUSTMENT_RANGE(MSP_SET_ADJUSTMENT_RANGE_Request req);
            /**
            out message: Get Cleanflight serial configuration
            */
            (L____________, MSP_CF_SERIAL_CONFIG_Reply) MSP_CF_SERIAL_CONFIG(MSP_CF_SERIAL_CONFIG_Request req);
            /**
            55 was MSP_SET_CF_SERIAL_CONFIG; serial ports are set through the CLI over MSP
            out message: Get voltage meter configuration
            */
            (L____________, MSP_VOLTAGE_METER_CONFIG_Reply) MSP_VOLTAGE_METER_CONFIG(MSP_VOLTAGE_METER_CONFIG_Request req);
            /**
            in message:  Set voltage meter configuration
            */
            (L____________, MSP_SET_VOLTAGE_METER_CONFIG_Reply) MSP_SET_VOLTAGE_METER_CONFIG(MSP_SET_VOLTAGE_METER_CONFIG_Request req);
            /**
            out message: Get sonar altitude [cm]
            */
            (L____________, MSP_SONAR_ALTITUDE_Reply) MSP_SONAR_ALTITUDE(MSP_SONAR_ALTITUDE_Request req);
            /**
            out message: Get PID controller
            */
            (L____________, MSP_PID_CONTROLLER_Reply) MSP_PID_CONTROLLER(MSP_PID_CONTROLLER_Request req);
            /**
            in message:  Set PID controller
            */
            (L____________, MSP_SET_PID_CONTROLLER_Reply) MSP_SET_PID_CONTROLLER(MSP_SET_PID_CONTROLLER_Request req);
            /**
            out message: Get arming configuration
            */
            (L____________, MSP_ARMING_CONFIG_Reply) MSP_ARMING_CONFIG(MSP_ARMING_CONFIG_Request req);
            /**
            in message:  Set arming configuration
            */
            (L____________, MSP_SET_ARMING_CONFIG_Reply) MSP_SET_ARMING_CONFIG(MSP_SET_ARMING_CONFIG_Request req);
            /**
            Baseflight MSP commands (64-89)
            out message: Get RX map (also returns number of channels total)
            */
            (L____________, MSP_RX_MAP_Reply) MSP_RX_MAP(MSP_RX_MAP_Request req);
            /**
            in message:  Set RX map, numchannels to set comes from MSP_RX_MAP
            */
            (L____________, MSP_SET_RX_MAP_Reply) MSP_SET_RX_MAP(MSP_SET_RX_MAP_Request req);
            /**
            in message:  Reboot settings
            */
            (L____________, MSP_REBOOT_Reply) MSP_REBOOT(MSP_REBOOT_Request req);
            /**
            out message: Get description of dataflash chip
            */
            (L____________, MSP_DATAFLASH_SUMMARY_Reply) MSP_DATAFLASH_SUMMARY(MSP_DATAFLASH_SUMMARY_Request req);
            /**
            out message: Get content of dataflash chip
            */
            (L____________, MSP_DATAFLASH_READ_Reply) MSP_DATAFLASH_READ(MSP_DATAFLASH_READ_Request req);
            /**
            in message:  Erase dataflash chip
            */
            (L____________, MSP_DATAFLASH_ERASE_Reply) MSP_DATAFLASH_ERASE(MSP_DATAFLASH_ERASE_Request req);
            /**
            out message: Get failsafe settings
            */
            (L____________, MSP_FAILSAFE_CONFIG_Reply) MSP_FAILSAFE_CONFIG(MSP_FAILSAFE_CONFIG_Request req);
            /**
            in message:  Set failsafe settings
            */
            (L____________, MSP_SET_FAILSAFE_CONFIG_Reply) MSP_SET_FAILSAFE_CONFIG(MSP_SET_FAILSAFE_CONFIG_Request req);
            /**
            out message: Get RX failsafe settings
            */
            (L____________, MSP_RXFAIL_CONFIG_Reply) MSP_RXFAIL_CONFIG(MSP_RXFAIL_CONFIG_Request req);
            /**
            in message:  Set RX failsafe settings
            */
            (L____________, MSP_SET_RXFAIL_CONFIG_Reply) MSP_SET_RXFAIL_CONFIG(MSP_SET_RXFAIL_CONFIG_Request req);
            /**
            out message: Get SD card state
            */
            (L____________, MSP_SDCARD_SUMMARY_Reply) MSP_SDCARD_SUMMARY(MSP_SDCARD_SUMMARY_Request req);
            /**
            out message: Get blackbox settings
            */
            (L____________, MSP_BLACKBOX_CONFIG_Reply) MSP_BLACKBOX_CONFIG(MSP_BLACKBOX_CONFIG_Request req);
            /**
            in message:  Set blackbox settings
            */
            (L____________, MSP_SET_BLACKBOX_CONFIG_Reply) MSP_SET_BLACKBOX_CONFIG(MSP_SET_BLACKBOX_CONFIG_Request req);
            /**
            out message: Get transponder settings
            */
            (L____________, MSP_TRANSPONDER_CONFIG_Reply) MSP_TRANSPONDER_CONFIG(MSP_TRANSPONDER_CONFIG_Request req);
            /**
            in message:  Set transponder settings
            */
            (L____________, MSP_SET_TRANSPONDER_CONFIG_Reply) MSP_SET_TRANSPONDER_CONFIG(MSP_SET_TRANSPONDER_CONFIG_Request req);
            /**
            out message: Get OSD settings
            */
            (L____________, MSP_OSD_CONFIG_Reply) MSP_OSD_CONFIG(MSP_OSD_CONFIG_Request req);
            /**
            in message:  Set OSD settings
            */
            (L____________, MSP_SET_OSD_CONFIG_Reply) MSP_SET_OSD_CONFIG(MSP_SET_OSD_CONFIG_Request req);
            /**
            out message: Get OSD characters
            */
            (L____________, MSP_OSD_CHAR_READ_Reply) MSP_OSD_CHAR_READ(MSP_OSD_CHAR_READ_Request req);
            /**
            in message:  Set OSD characters
            */
            (L____________, MSP_OSD_CHAR_WRITE_Reply) MSP_OSD_CHAR_WRITE(MSP_OSD_CHAR_WRITE_Request req);
            /**
            out message: Get VTX settings
            */
            (L____________, MSP_VTX_CONFIG_Reply) MSP_VTX_CONFIG(MSP_VTX_CONFIG_Request req);
            /**
            in message:  Set VTX settings
            */
            (L____________, MSP_SET_VTX_CONFIG_Reply) MSP_SET_VTX_CONFIG(MSP_SET_VTX_CONFIG_Request req);
            /**
            Betaflight Additional Commands (90-99)
            out message: Get advanced configuration
            */
            (L____________, MSP_ADVANCED_CONFIG_Reply) MSP_ADVANCED_CONFIG(MSP_ADVANCED_CONFIG_Request req);
            /**
            in message:  Set advanced configuration
            */
            (L____________, MSP_SET_ADVANCED_CONFIG_Reply) MSP_SET_ADVANCED_CONFIG(MSP_SET_ADVANCED_CONFIG_Request req);
            /**
            out message: Get filter configuration
            */
            (L____________, MSP_FILTER_CONFIG_Reply) MSP_FILTER_CONFIG(MSP_FILTER_CONFIG_Request req);
            /**
            in message:  Set filter configuration
            */
            (L____________, MSP_SET_FILTER_CONFIG_Reply) MSP_SET_FILTER_CONFIG(MSP_SET_FILTER_CONFIG_Request req);
            /**
            out message: Get advanced PID settings
            */
            (L____________, MSP_PID_ADVANCED_Reply) MSP_PID_ADVANCED(MSP_PID_ADVANCED_Request req);
            /**
            in message:  Set advanced PID settings
            */
            (L____________, MSP_SET_PID_ADVANCED_Reply) MSP_SET_PID_ADVANCED(MSP_SET_PID_ADVANCED_Request req);
            /**
            out message: Get sensor configuration
            */
            (L____________, MSP_SENSOR_CONFIG_Reply) MSP_SENSOR_CONFIG(MSP_SENSOR_CONFIG_Request req);
            /**
            in message:  Set sensor configuration
            */
            (L____________, MSP_SET_SENSOR_CONFIG_Reply) MSP_SET_SENSOR_CONFIG(MSP_SET_SENSOR_CONFIG_Request req);
            /**
            in/out message: Camera control
            */
            (L____________, MSP_CAMERA_CONTROL_Reply) MSP_CAMERA_CONTROL(MSP_CAMERA_CONTROL_Request req);
            /**
            in message:  Enable/disable arming
            */
            (L____________, MSP_SET_ARMING_DISABLED_Reply) MSP_SET_ARMING_DISABLED(MSP_SET_ARMING_DISABLED_Request req);
            /**
            Multiwii original MSP commands (101-139)
            out message: Cycletime &amp; errors_count &amp; sensor present &amp; box activation &amp; current setting
            number
            */
            (L____________, MSP_STATUS_Reply) MSP_STATUS(MSP_STATUS_Request req);
            /**
            out message: 9 DOF
            */
            (L____________, MSP_RAW_IMU_Reply) MSP_RAW_IMU(MSP_RAW_IMU_Request req);
            /**
            out message: Servos
            */
            (L____________, MSP_SERVO_Reply) MSP_SERVO(MSP_SERVO_Request req);
            /**
            out message: Motors
            */
            (L____________, MSP_MOTOR_Reply) MSP_MOTOR(MSP_MOTOR_Request req);
            /**
            out message: RC channels and more
            */
            (L____________, MSP_RC_Reply) MSP_RC(MSP_RC_Request req);
            /**
            out message: Fix, numsat, lat, lon, alt, speed, ground course
            */
            (L____________, MSP_RAW_GPS_Reply) MSP_RAW_GPS(MSP_RAW_GPS_Request req);
            /**
            out message: Distance home, direction home
            */
            (L____________, MSP_COMP_GPS_Reply) MSP_COMP_GPS(MSP_COMP_GPS_Request req);
            /**
            out message: 2 angles 1 heading
            */
            (L____________, MSP_ATTITUDE_Reply) MSP_ATTITUDE(MSP_ATTITUDE_Request req);
            /**
            out message: Altitude, variometer
            */
            (L____________, MSP_ALTITUDE_Reply) MSP_ALTITUDE(MSP_ALTITUDE_Request req);
            /**
            out message: Vbat, powermetersum, rssi if available on RX
            */
            (L____________, MSP_ANALOG_Reply) MSP_ANALOG(MSP_ANALOG_Request req);
            /**
            out message: RC rate, rc expo, rollpitch rate, yaw rate, dyn throttle PID
            */
            (L____________, MSP_RC_TUNING_Reply) MSP_RC_TUNING(MSP_RC_TUNING_Request req);
            /**
            out message: P I D coeff (9 are used currently)
            */
            (L____________, MSP_PID_Reply) MSP_PID(MSP_PID_Request req);
            /**
            out message: The aux switch names
            */
            (L____________, MSP_BOXNAMES_Reply) MSP_BOXNAMES(MSP_BOXNAMES_Request req);
            /**
            out message: The PID names
            */
            (L____________, MSP_PIDNAMES_Reply) MSP_PIDNAMES(MSP_PIDNAMES_Request req);
            /**
